  "args": {
    "research_concepts": [
      "offensive lineups",
      "shot mix",
      "shot distribution",
      "personnel effects",
      "lineup effects on shot selection"
    ],
    "methodological_questions": [
      "How to define and measure 'shot mix'?",
      "How to attribute changes in shot mix to 'offensive five' personnel?",
      "How to isolate lineup effects from confounding factors (e.g., opponent, game state)?",
      "What statistical methods are appropriate for analyzing lineup effects on shot mix?"
    ],
    "query": "Impact of offensive lineups on shot mix and shot distribution, and methods for detecting personnel effects on shot selection."
  }
}

