  "cited": [
   "identifiers of prior work relied on"
  ],
  "summary": "string"
 },
 "risks": [
  {
   "code": "one of RISK_CODES",
   "text": "string"
  }
 ],
 "predicted_outcome": {
  "supported": "probability",
  "rejected": "probability",
  "untestable": "probability",
  "artifact": "probability",
  "uncertain": "probability"
 },
 "decision": "proceed | proceed_with_changes | do_not_proceed",
 "design": {
  "estimand": "string",
  "unit": "string",
  "sample": "string",
  "power": "string",
  "controls": "string",
  "falsification": "string",
  "multiplicity": "string",
  "decision_rule": "string",
  "data_version": "string"
 }
}
Field guidance:
- historical_evidence and failed_approaches: only records returned by a tool, with the status as recorded; empty lists
  if nothing relevant was returned.
- testability.p_testable: probability that the question can be answered with the stated data at useful statistical power.
- prior_work.already_answered: whether retrieved earlier work already answered substantially the same question.
  Use "unknown" if no earlier work was retrieved. List identifiers you relied on in prior_work.cited.
- predicted_outcome: probabilities (summing to 1) of what a competent test of the question as posed would conclude:
  supported, rejected (adequately powered null), untestable (cannot be tested with this data), artifact (apparent
  effect produced by a flaw), uncertain (inconclusive or inadequately tested).
- decision: proceed, proceed_with_changes (state the changes in design), or do_not_proceed.
- design: a pre-registration-quality plan even if the decision is do_not_proceed (then describe the minimum viable test).

{
  "research_concepts": [
    "offensive lineups",
    "shot mix",
    "shot distribution",
    "personnel effects",
    "lineup effects on shot selection"
  ],
  "methodological_questions": [
    "How to define and measure 'shot mix'?",
    "How to attribute changes in shot mix to 'offensive five' personnel?",
    "How to isolate lineup effects from confounding factors (e.g., opponent, game state)?",
    "What statistical methods are appropriate for analyzing lineup effects on shot mix?"
  ],
  "historical_evidence": [
    {
      "id": "FAM:SF-TMP-009",
      "status_as_recorded": "artifact",
      "finding": "Effect shrinks from -0.0255 to -0.0063 without lineup FE and the same-shooter placebo on other play types is -0.0071/-0.0075, consistent with shooter-level confound."
    },
    {
      "id": "FAM:SF-TMP-012",
      "status_as_recorded": "artifact",
      "finding": "Reproduced excess 0.4080 CI [0.378,0.438]; G within-unit perm at 0.25: obs 0.3798 null 0.3744 resid +0.0054 z 0.40; asym neg-pos 0.0176 p 0.258; drift-centered tail mass ratio 1.007."
    },
    {
      "id": "FAM:SF09",
      "status_as_recorded": "inconclusive",
      "finding": "[APPA-057] Baseline 1.210 n=960,764. After PUTBACK only 1.097 d=-0.113 n=15,898. After POST_UP only 1.091 d=-0.119 n=76,329. Stacked 1.138 d=-0.071 n=1,047 vs additive prediction -0.232. Mitchell after PUTBACK 0.919 vs 1 [cut; read_family for the full text]"
    },
    {
      "id": "FAM:SF-TMP-021",
      "status_as_recorded": "inconclusive",
      "finding": "any_fta 3->4 -0.151 vs placebos -5.556/-9.655; rim_pct +0.015 vs +1.666/+2.077; pts +0.020."
    }
  ],
  "failed_approaches": [
    {
      "id": "FAM:SF-TMP-009",
      "what_failed": "Assessing PULL_UP exposure effects without accounting for lineup fixed effects",
      "why": "C_artifact (apparent effect produced by a construction, selection or labelling flaw), LIM:confounding"
    },
    {
      "id": "FAM:SF-TMP-012",
      "what_failed": "Estimates that select units on a large drop and compare them with matched controls without appropriate null models",
      "why": "C_artifact (apparent effect produced by a construction, selection or labelling flaw), LIM:drift, LIM:insufficient_exposure, LIM:selection_or_regression_to_the_mean"
    },
    {
      "id": "FAM:SF-TMP-021",
      "what_failed": "Pilot test of penalty-state adaptation where penalty contrast was not distinct from placebo contrasts and standard errors were not printed",
      "why": "E_unclear (mechanism unclear from the records)"
    }
  ],
  "evidence_establishes": [
    "Lineup composition can be a significant confounder when studying individual player or play-type effects (FAM:SF-TMP-009).",
    "The inclusion of lineup fixed effects can significantly alter observed effects, highlighting their importance (FAM:SF-TMP-009).",
    "The necessity of placebo tests to differentiate true effects from artifacts (FAM:SF-TMP-009, FAM:SF-TMP-021).",
    "The risk of spurious effects due to selection rules, drift, or regression to the mean (FAM:SF-TMP-012)."
  ],
  "evidence_does_not_establish": [
    "Whether and how changes in the offensive five specifically cause changes in shot mix.",
    "The magnitude or direction of lineup effects on shot mix.",
    "Specific robust methodologies for isolating and measuring lineup effects on shot mix.",
    "The statistical power required for this specific research question.",
    "Whether the observed effects in FAM:SF-TMP-009 were due to changes in shot mix or other factors."
  ],
  "own_inferences": [
    "The research question is directly aligned with the implication from FAM:SF-TMP-009 that lineup effects are substantial and need to be understood, either as confounders or as direct effects.",
    "The available data (play-by-play, substitutions, defensive matchups) is rich enough to construct offensive lineups and analyze shot characteristics at a granular level."
  ],
  "uncertainties": [
    "The precise definition and quantification of 'shot mix' (e.g., specific shot zones, shot types, or average distance).",
    "The operational definition of 'changing the offensive five' (e.g., comparing specific stable lineups, or analyzing the impact of single-player substitutions).",
    "How to adequately control for dynamic game context (e.g., score differential, time remaining, opponent personnel, tactical adjustments) that might covary with lineup changes and influence shot mix.",
    "The frequency and variability of lineup changes, which impacts the sample size for observing distinct lineup effects."
  ],
  "historical_effect": {
    "changed_decision": "yes",
    "explanation": "The historical evidence, particularly FAM:SF-TMP-009, strongly emphasizes that lineup composition is a critical factor influencing observed player actions and outcomes, potentially acting as a significant confounder. This reinforces the importance and testability of the proposed research question, which directly aims to measure these 'personnel effects' on shot mix. It shifts the decision from a potentially more cautious 'proceed_with_changes' to a confident 'proceed', with a clear focus on robust controls and placebo tests as suggested by the historical records."
  },
  "testability": {
    "p_testable": 0.8,
    "blocking_constraints": []
  },
  "prior_work": {
    "already_answered": "no",
    "cited": [
      "FAM:SF-TMP-009"
    ],
    "summary": "No prior work directly answers whether changing the offensive five itself moves shot mix. However, FAM:SF-TMP-009 indicates that lineup fixed effects are crucial for understanding player-level outcomes (PULL_UP decline), suggesting that lineup changes *do* have a substantial impact and are important to study. This study, while not directly addressing shot mix, provides strong indirect evidence that personnel effects via lineups are real and measurable."
  },
  "risks": [
    {
      "code": "CONFOUNDING",
      "text": "Game state, opponent defensive schemes, coach's tactical adjustments, and player fatigue can confound the observed effects of a lineup change on shot mix. These factors often covary with lineup changes (e.g., specific lineups used in specific game situations)."
    },
    {
      "code": "SAMPLE_SIZE_POWER",
      "text": "Many unique offensive lineups may have limited minutes played, especially in critical game situations, potentially leading to insufficient sample size for robust statistical inference, particularly for specific lineup comparisons or rare events within shot mix."
    },
    {
      "code": "EXPOSURE_SPARSITY",
      "text": "Some specific lineup configurations or transitions between configurations might be rare, making it difficult to accumulate enough data to reliably estimate their effect on shot mix."
    },
    {
      "code": "MEASURE_RELIABILITY",
      "text": "The definition of 'shot mix' needs to be precise and its measurement reliable. If it's a composite measure, its components' reliability and interpretability must be considered."
    },
    {
      "code": "DRIFT_NONSTATIONARITY",
      "text": "Player performance, team strategy, and league-wide trends can change over the three seasons. Lineup effects might not be stationary over time, requiring careful temporal controls or season-specific analysis."
    }
  ],
  "predicted_outcome": {
    "supported": 0.5,
    "rejected": 0.2,
    "untestable": 0.1,
    "artifact": 0.1,
    "uncertain": 0.1
  },
  "decision": "proceed",
  "design": {
    "estimand": "The causal effect of a change in the offensive five on the team's subsequent shot mix (e.g., proportion of 3-point attempts, proportion of attempts at the rim, average shot distance, proportion of mid-range jumpers) over a defined possession window.",
    "unit": "Offensive possession. Analysis will consider sequences of possessions following a substitution that changes the offensive five.",
    "sample": "All offensive possessions from NBA 2022-23, 2023-24, and 2024-25 regular seasons and playoffs. Focus on possessions immediately following a substitution that alters the offensive five, comparing the shot mix of the new lineup to the shot mix of the previous lineup (or a counterfactual based on other similar lineups).",
    "power": "Power analysis will be conducted after initial data exploration to determine the minimum detectable effect size for common lineup changes, given the observed variance in shot mix and lineup frequencies. Initial focus will be on frequently used lineups and high-volume shot types.",
    "controls": "Fixed effects for game, team, period, and opponent. Control variables for game state (score differential, time remaining), previous possession outcome, and the specific players involved in the substitution. Consider using a difference-in-differences approach or regression discontinuity design around substitutions if feasible. Match on opponent defensive personnel and scheme where possible using defensive matchup data. Include player-level fixed effects for the players remaining on the court to isolate the effect of the changed personnel.",
    "falsification": "Placebo tests: 1) Analyze 'changes' in shot mix for lineups that remained unchanged across a nominal substitution point (e.g., comparing shot mix before/after a timeout without personnel change). 2) Examine whether 'changes' in shot mix occur when only defensive personnel change without an offensive lineup change. 3) Test for effects on irrelevant outcomes or for effects that precede the lineup change (look-ahead bias).",
    "multiplicity": "Adjust p-values for multiple comparisons if testing effects on several distinct 'shot mix' metrics (e.g., 3P%, Rim%, Mid-range%) or multiple specific lineup changes. Prioritize a primary shot mix metric (e.g., overall average shot distance or 3P%) to reduce multiplicity concerns.",
    "decision_rule": "The hypothesis will be considered supported if there is a statistically significant (p < 0.05, two-tailed, after multiplicity adjustment if applicable) and substantively meaningful change in the primary shot mix metric attributable to the change in offensive five, and if falsification tests do not reveal spurious effects.",
    "data_version": "NBA 2022-23, 2023-24, 2024-25 regular season and playoffs data from NBA stats API (play-by-play, substitution rotation, defensive matchup, box score) and derived play-type possession records."
  }
}

